export interface Pixels {
  width: number;
  height: number;
  /** Interleaved 8-bit R, G, B, width * height * 3 bytes. */
  rgb: Buffer;
  /** One 8-bit alpha byte per pixel, or null when the image is opaque. */
  alpha: Buffer | null;
}

const SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const CHANNELS: Record<number, number> = { 0: 1, 2: 3, 3: 1, 6: 4 };

function paeth(a: number, b: number, c: number): number {
  const p = a + b - c;
  const pa = Math.abs(p - a);
  const pb = Math.abs(p - b);
  const pc = Math.abs(p - c);
  return pa <= pb && pa <= pc ? a : pb <= pc ? b : c;
}

/** Undoes PNG's per-row filters (types 0 to 4) on the inflated rows. */
function unfilter(raw: Buffer, height: number, stride: number, bpp: number): Buffer {
  const out = Buffer.alloc(height * stride);
  for (let y = 0; y < height; y++) {
    const type = raw[y * (stride + 1)]!;
    const src = y * (stride + 1) + 1;
    const dst = y * stride;
    for (let i = 0; i < stride; i++) {
      const left = i >= bpp ? out[dst + i - bpp]! : 0;
      const up = y > 0 ? out[dst - stride + i]! : 0;
      const upLeft = y > 0 && i >= bpp ? out[dst - stride + i - bpp]! : 0;
      const x = raw[src + i]!;
      let v: number;
      switch (type) {
        case 0: v = x; break;
        case 1: v = x + left; break;
        case 2: v = x + up; break;
        case 3: v = x + ((left + up) >> 1); break;
        case 4: v = x + paeth(left, up, upLeft); break;
        default: throw new Error(`PNG row ${y} has filter type ${type}`);
      }
      out[dst + i] = v & 255;
    }
  }
  return out;
}

/** Reads an 8-bit, non-interlaced PNG of colour type 0, 2, 3 or 6. Anything else throws. */
export function decodePng(png: Buffer): Pixels {
  if (png.length < 8 || !png.subarray(0, 8).equals(SIGNATURE)) throw new Error('Not a PNG file');
  let width = 0;
  let height = 0;
  let depth = 0;
  let colourType = -1;
  let interlace = 0;
  let palette: Buffer | null = null;
  let paletteAlpha: Buffer | null = null;
  const idat: Buffer[] = [];
  for (let pos = 8; pos + 8 <= png.length; ) {
    const length = png.readUInt32BE(pos);
    const kind = png.toString('latin1', pos + 4, pos + 8);
    const data = png.subarray(pos + 8, pos + 8 + length);
    if (kind === 'IHDR') {
      width = data.readUInt32BE(0);
      height = data.readUInt32BE(4);
      depth = data[8]!;
      colourType = data[9]!;
      interlace = data[12]!;
    } else if (kind === 'PLTE') palette = data;
    else if (kind === 'tRNS') paletteAlpha = data;
    else if (kind === 'IDAT') idat.push(data);
    else if (kind === 'IEND') break;
    pos += 12 + length;
  }
  const channels = CHANNELS[colourType];
  if (!channels || depth !== 8 || interlace !== 0 || !width || !height) {
    throw new Error(`Unsupported PNG: colour type ${colourType}, ${depth} bit, interlace ${interlace}`);
  }
  if (colourType === 3 && !palette) throw new Error('PNG palette is missing');

  const stride = width * channels;
  const raw = inflateSync(Buffer.concat(idat));
  if (raw.length !== height * (stride + 1)) throw new Error('PNG pixel data has the wrong length');
  const px = unfilter(raw, height, stride, channels);

  const count = width * height;
  const rgb = Buffer.alloc(count * 3);
  const hasAlpha = colourType === 6 || (colourType === 3 && paletteAlpha !== null);
  const alpha = hasAlpha ? Buffer.alloc(count) : null;
  for (let i = 0; i < count; i++) {
    const o = i * 3;
    if (colourType === 6) {
      rgb[o] = px[i * 4]!;
      rgb[o + 1] = px[i * 4 + 1]!;
      rgb[o + 2] = px[i * 4 + 2]!;
      alpha![i] = px[i * 4 + 3]!;
    } else if (colourType === 2) {
      rgb[o] = px[i * 3]!;
      rgb[o + 1] = px[i * 3 + 1]!;
      rgb[o + 2] = px[i * 3 + 2]!;
    } else if (colourType === 0) {
      rgb[o] = rgb[o + 1] = rgb[o + 2] = px[i]!;
    } else {
      const index = px[i]!;
      rgb[o] = palette![index * 3] ?? 0;
      rgb[o + 1] = palette![index * 3 + 1] ?? 0;
      rgb[o + 2] = palette![index * 3 + 2] ?? 0;
      if (alpha) alpha[i] = paletteAlpha![index] ?? 255;
    }
  }
  return { width, height, rgb, alpha };
}
